#!/usr/bin/env python3
"""TASK-20260922-0e10d1 J5 diagnostic D1 analysis. REVIEW DIAGNOSTIC ONLY.

Combines the census factor lists (factorizations.json, read-only) with any
cofactor splits returned by d1_deployed_cofactors.py (out/d1_*.json), rebuilds
the divisor lattice per branch, and re-evaluates with mpmath (mp.dps 110):
E1 (frozen expression) on both branches, E2 (Cheon 2006 Thm 2 shape) on r+1.
A branch whose cofactor was fully split into PARI-proven primes becomes
'exact (diagnostic)'; otherwise it stays 'bound'. Nothing here replaces any
census value; it tests whether 'undetermined' is a property of the integers or
of the census budget.
"""
import json
import sys
from pathlib import Path

import mpmath
from mpmath import mp, mpf, sqrt, log

mp.dps = 110
OUT = Path(__file__).resolve().parents[1] / "out"
RUN = Path("/home/user/crypto-autoresearcher/experiments/EXP-AUXIN-7e2e3d/runs/RUN-AUXIN-fd1edc")
CEIL = mpf("0.40")


def lg2(x):
    return log(x) / log(mpf(2))


def divisors(pp, cof):
    divs = [1]
    for p in sorted(pp):
        new = []
        pe = 1
        for _ in range(pp[p]):
            pe *= p
            new.extend(d * pe for d in divs)
        divs += new
    if cof is not None:
        divs = divs + [d * cof for d in divs]
    return sorted(set(divs))


def main():
    fz = json.loads((RUN / "factorizations.json").read_text())["curves"]
    splits = {}
    for f in sorted(OUT.glob("d1*.json")):
        if f.name == "d1_analysis.json":
            continue
        txt = f.read_text()
        # cypari2.allocatemem prints a notice line to stdout before the JSON body
        start = txt.find("\n{")
        body = txt if txt.startswith("{") else (txt[start + 1:] if start >= 0 else "")
        try:
            doc = json.loads(body)
        except Exception:
            continue
        rank = {"factored": 2, "partial_no_complete_split": 1}
        for r_ in doc.get("results", []):
            k = (r_["curve_id"], r_["branch"])
            r_["source_file"] = f.name
            if k not in splits or rank.get(r_.get("status"), 0) >= rank.get(splits[k].get("status"), 0):
                splits[k] = r_
    rows = {}
    for cid, rec in fz.items():
        r = int(rec["r"])
        lr = lg2(mpf(r))
        row = {}
        for key, br, m in (("r_minus_1", "r-1", r - 1), ("r_plus_1", "r+1", r + 1)):
            pp = {int(p): int(e) for p, e in rec[key]["prime_powers"].items()}
            cof = rec[key].get("unfactored_cofactor")
            cof = int(cof) if cof is not None else None
            kind = "exact (census)" if cof is None else "bound (census)"
            s = splits.get((cid, br))
            atoms = []
            if cof is not None and s and s.get("status") == "factored" and s.get("product_ok"):
                if s.get("all_proven_prime"):
                    for p, e in s["factors"]:
                        pp[int(p)] = pp.get(int(p), 0) + int(e)
                    cof = None
                    kind = "exact (diagnostic D1: census factors + PARI-proven split of the cofactor)"
            elif cof is not None and s and s.get("status") == "partial_no_complete_split" and s.get("primes"):
                # partial split: found primes join the lattice; each remaining composite is an
                # opaque atom (products of subsets are still divisors of m), so the branch stays a BOUND
                for p in s["primes"]:
                    pp[int(p)] = pp.get(int(p), 0) + 1
                atoms = [int(x) for x in s["remaining_composites"]]
                cof = None
                kind = "bound (diagnostic D1b: census factors + partial ECM split; composite atoms remain)"
            prod = 1
            for p, e in pp.items():
                prod *= p ** e
            for a in atoms:
                prod *= a
            if cof is not None:
                prod *= cof
            assert prod == m
            assert (cof is None and not atoms) == kind.startswith("exact")
            divs = divisors(pp, cof)
            for a in atoms:
                divs = sorted(set(divs + [d * a for d in divs]))
            b1 = b2 = None
            for d in divs:
                v1 = lg2(sqrt(mpf(m) / d) + sqrt(mpf(d))) / lr
                v2 = lg2(sqrt(mpf(m) / d) + mpf(d)) / lr
                if b1 is None or v1 < b1[0]:
                    b1 = (v1, d)
                if b2 is None or v2 < b2[0]:
                    b2 = (v2, d)
            row[br] = {"kind": kind, "E1": mpmath.nstr(b1[0], 20), "E1_d_bits": b1[1].bit_length(),
                       "E2": mpmath.nstr(b2[0], 20), "E2_d_bits": b2[1].bit_length(),
                       "largest_prime_bits": max(pp).bit_length() if pp else None,
                       "remaining_cofactor_bits": (None if cof is None else cof.bit_length()) if not atoms else [a.bit_length() for a in atoms],
                       "d1_status": None if s is None else s.get("status")}
        rows[cid] = row

    def cls(vals):
        if any(mpf(v) <= CEIL for v, k in vals):
            return "escalate"
        if all(k.startswith("exact") for v, k in vals):
            return "not_escalating"
        return "undetermined"
    readings = {}
    for name, fn in (
        ("untyped_frozen_expr", lambda x: [(x["r-1"]["E1"], x["r-1"]["kind"]), (x["r+1"]["E1"], x["r+1"]["kind"])]),
        ("r_minus_1_typed", lambda x: [(x["r-1"]["E1"], x["r-1"]["kind"])]),
        ("r_plus_1_typed_thm2_shape", lambda x: [(x["r+1"]["E2"], x["r+1"]["kind"])]),
        ("typed_union", lambda x: [(x["r-1"]["E1"], x["r-1"]["kind"]), (x["r+1"]["E2"], x["r+1"]["kind"])]),
    ):
        res = {}
        for cid, x in rows.items():
            res.setdefault(cls(fn(x)), []).append(cid)
        readings[name] = res
    json.dump({"mpmath_version": mpmath.__version__, "rows": rows, "readings_diagnostic": readings,
               "splits_used": {f"{k[0]}:{k[1]}": {kk: v[kk] for kk in ("status", "wall_seconds", "seconds", "cap_seconds", "source_file")
                                                  if kk in v} for k, v in splits.items()}},
              sys.stdout, indent=1)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""TASK-20260922-0e10d1 -- compare the D1/D1b cofactor splits of the four census
r-1 E_bound branches with JK20's published b(pm) (bits of the largest prime
divisor of p - 1), and re-check every split factor with sympy.isprime (BPSW) as
a second library beside PARI's proof. Review diagnostic; read-only inputs."""
import json, sys
from pathlib import Path
from sympy import isprime
OUT = Path(__file__).resolve().parents[1] / "out"
RUN = Path("/home/user/crypto-autoresearcher/experiments/EXP-AUXIN-7e2e3d/runs/RUN-AUXIN-fd1edc")
JK20 = {"Ed25519-L": 138, "NIST-P-384": 281, "brainpoolP384r1": 206, "NIST-P-521": 391}
fz = json.loads((RUN / "factorizations.json").read_text())["curves"]
def load(name):
    t = (OUT / name).read_text()
    return json.loads(t if t.startswith("{") else t[t.find("\n{") + 1:])
splits = {}
for name in ("d1_pari_rminus1_easy.json", "d1b_ecm_rminus1.json"):
    for r in load(name)["results"]:
        splits[r["curve_id"]] = [int(p) for p, e in r["factors"] for _ in range(int(e))] if "factors" in r else None
out = {}
for cid, bpm in JK20.items():
    rec = fz[cid]["r_minus_1"]
    cof = int(rec["unfactored_cofactor"])
    known = [int(p) for p in rec["prime_powers"]]
    fs = splits.get(cid)
    prod = 1
    for f in fs:
        prod *= f
    allp = known + fs
    out[cid] = {"cofactor_bits": cof.bit_length(), "split_bits": sorted(f.bit_length() for f in fs),
                "split_product_equals_cofactor": prod == cof,
                "split_factors_sympy_isprime": all(isprime(f) for f in fs),
                "largest_prime_bits_after_split": max(allp).bit_length(), "JK20_b_pm": bpm,
                "agrees_with_JK20": max(allp).bit_length() == bpm}
json.dump(out, sys.stdout, indent=1)

#!/usr/bin/env python3
"""TASK-20260922-0e10d1 J7 PTM-1 analysis. REVIEW COMPUTATION, read-only inputs.

Inputs: out/ptm1_raw.json (ptm1_random_primes.py), optional out/ptm1_resolve.json
(supplementary resolution pass, NOT like-for-like, reported separately), and
out/j5_j6_analysis.json (deployed rows, this reviewer's recomputation).

Per random prime r and branch m in {r-1, r+1}:
  E1_m = min_d log2(sqrt(m/d)+sqrt(d))/log2 r   (frozen expression)
  E2_m = min_d log2(sqrt(m/d)+d)/log2 r         (Cheon 2006 Thm 2 shape; r+1 only)
  floor1_m = (1 + log2(m)/4)/log2 r
over the known divisor lattice ({d|F} u {d*C|d|F} if a cofactor C remains).
Classification against the frozen ceiling 0.40 (card RA-4): a known-divisor
value <= 0.40 ESCALATES (it is an explicit witness, true E <= it); a complete
lattice with min > 0.40 is NOT escalating; otherwise UNDETERMINED (never inert).
Inert (>= 0.49) is asserted only on complete lattices.
Intervals: exact Clopper-Pearson 95%, computed with mpmath regularized
incomplete beta and bisection. Undetermined rows are reported at both
extremes. Fisher exact two-sided test via math.comb.
Cross-check: the producer's e_eval.evaluate_E is imported READ-ONLY
(sys.dont_write_bytecode) and evaluated on the same factor lists.
"""
import json
import math
import sys
from pathlib import Path

sys.dont_write_bytecode = True
import mpmath  # noqa: E402
from mpmath import mp, mpf, sqrt, log  # noqa: E402

mp.dps = 60
OUT = Path(__file__).resolve().parents[1] / "out"
IMPL = "/home/user/crypto-autoresearcher/experiments/EXP-AUXIN-7e2e3d/implementation"
CEIL = mpf("0.40")
INERT = mpf("0.49")


def lg2(x):
    return log(x) / log(mpf(2))


def divisors(pp, cof):
    divs = [1]
    for p in sorted(pp):
        new = []
        pe = 1
        for _ in range(pp[p]):
            pe *= p
            new.extend(d * pe for d in divs)
        divs += new
    if cof is not None:
        divs = divs + [d * cof for d in divs]
    return sorted(set(divs))


def branch_eval(r, m, rec):
    pp = {int(p): int(e) for p, e in rec["prime_powers"].items()}
    cof = rec.get("unfactored_cofactor")
    cof = int(cof) if cof is not None else None
    lr = lg2(mpf(r))
    b1 = None
    b2 = None
    for d in divisors(pp, cof):
        v1 = lg2(sqrt(mpf(m) / d) + sqrt(mpf(d))) / lr
        v2 = lg2(sqrt(mpf(m) / d) + mpf(d)) / lr
        if b1 is None or v1 < b1[0]:
            b1 = (v1, d)
        if b2 is None or v2 < b2[0]:
            b2 = (v2, d)
    fl1 = (1 + lg2(mpf(m)) / 4) / lr
    return {"complete": cof is None, "cof_bits": None if cof is None else cof.bit_length(),
            "E1": b1[0], "E1_d_bits": b1[1].bit_length(), "E2": b2[0], "E2_d_bits": b2[1].bit_length(),
            "floor1": fl1, "E1_minus_floor1": b1[0] - fl1}


def classify(vals_complete):
    """vals_complete: list of (value, complete) for the branches in the reading."""
    if any(v <= CEIL for v, c in vals_complete):
        return "escalate"
    if all(c for v, c in vals_complete):
        return "not_escalating"
    return "undetermined"


def classify_inert(vals_complete):
    if any(v < INERT for v, c in vals_complete):
        return "not_inert"
    if all(c for v, c in vals_complete):
        return "inert"
    return "undetermined"


def cp_interval(k, n, alpha=0.05):
    def inv(p, a, b):
        lo, hi = mpf(0), mpf(1)
        for _ in range(200):
            mid = (lo + hi) / 2
            if mpmath.betainc(a, b, 0, mid, regularized=True) < p:
                lo = mid
            else:
                hi = mid
        return (lo + hi) / 2
    lo = mpf(0) if k == 0 else inv(alpha / 2, k, n - k + 1)
    hi = mpf(1) if k == n else inv(1 - alpha / 2, k + 1, n - k)
    return [float(lo), float(hi)]


def fisher_two_sided(a, b, c, d):
    """2x2 [[a,b],[c,d]]; rows = groups, cols = (escalate, not)."""
    n1, n2, k = a + b, c + d, a + c
    N = n1 + n2
    def p(x):
        return math.comb(n1, x) * math.comb(n2, k - x) / math.comb(N, k)
    p0 = p(a)
    lo, hi = max(0, k - n2), min(k, n1)
    return sum(p(x) for x in range(lo, hi + 1) if p(x) <= p0 * (1 + 1e-12))


def quantiles(xs):
    xs = sorted(xs)
    n = len(xs)
    if n == 0:
        return {}
    def q(t):
        i = t * (n - 1)
        lo = int(math.floor(i))
        hi = min(lo + 1, n - 1)
        return xs[lo] + (xs[hi] - xs[lo]) * (i - lo)
    return {"n": n, "min": xs[0], "q25": q(0.25), "median": q(0.5), "q75": q(0.75), "max": xs[-1]}


def analyze(raw, label):
    rows = []
    for rec in raw["primes"]:
        r = int(rec["r"])
        b = {"r-1": branch_eval(r, r - 1, rec["branches"]["r-1"]),
             "r+1": branch_eval(r, r + 1, rec["branches"]["r+1"])}
        untyped = [(b["r-1"]["E1"], b["r-1"]["complete"]), (b["r+1"]["E1"], b["r+1"]["complete"])]
        att = "r-1" if b["r-1"]["E1"] <= b["r+1"]["E1"] else "r+1"
        rows.append({
            "i": rec["i"], "r_bits": r.bit_length(),
            "r-1": {k: (mpmath.nstr(v, 17) if isinstance(v, mpmath.mpf) else v) for k, v in b["r-1"].items()},
            "r+1": {k: (mpmath.nstr(v, 17) if isinstance(v, mpmath.mpf) else v) for k, v in b["r+1"].items()},
            "E_min_untyped": mpmath.nstr(min(b["r-1"]["E1"], b["r+1"]["E1"]), 17),
            "attaining_branch": att,
            "E_min_minus_floor_attaining": mpmath.nstr(b[att]["E1_minus_floor1"], 6),
            "complete_both": b["r-1"]["complete"] and b["r+1"]["complete"],
            "cls_untyped": classify(untyped),
            "cls_rminus1": classify([untyped[0]]),
            "cls_rplus1_frozen": classify([untyped[1]]),
            "cls_rplus1_thm2": classify([(b["r+1"]["E2"], b["r+1"]["complete"])]),
            "cls_typed_union": classify([untyped[0], (b["r+1"]["E2"], b["r+1"]["complete"])]),
            "inert_untyped": classify_inert(untyped),
            "inert_rminus1": classify_inert([untyped[0]]),
        })
    n = len(rows)
    summary = {}
    for key in ("cls_untyped", "cls_rminus1", "cls_rplus1_frozen", "cls_rplus1_thm2", "cls_typed_union",
                "inert_untyped", "inert_rminus1"):
        cnt = {}
        for r_ in rows:
            cnt[r_[key]] = cnt.get(r_[key], 0) + 1
        pos = "escalate" if key.startswith("cls") else "inert"
        k = cnt.get(pos, 0)
        u = cnt.get("undetermined", 0)
        summary[key] = {"counts": cnt, "n": n,
                        "fraction_lower": k / n, "fraction_upper": (k + u) / n,
                        "cp95_at_lower": cp_interval(k, n), "cp95_at_upper": cp_interval(k + u, n)}
    dist_complete = [float(mpf(r_[b]["E1_minus_floor1"])) for r_ in rows for b in ("r-1", "r+1") if r_[b]["complete"]]
    dist_rowmin = [float(mpf(r_["E_min_minus_floor_attaining"])) for r_ in rows if r_["complete_both"]]
    dist_rowmin_all = [float(mpf(r_["E_min_minus_floor_attaining"])) for r_ in rows]
    summary["dist_E1_minus_floor1_complete_branches"] = quantiles(dist_complete)
    summary["dist_rowmin_minus_floor_complete_rows"] = quantiles(dist_rowmin)
    summary["dist_rowmin_minus_floor_all_rows_bounds_included"] = quantiles(dist_rowmin_all)
    summary["complete_branch_count"] = sum(1 for r_ in rows for b in ("r-1", "r+1") if r_[b]["complete"])
    summary["complete_row_count"] = sum(1 for r_ in rows if r_["complete_both"])
    summary["min_E_untyped"] = min(float(mpf(r_["E_min_untyped"])) for r_ in rows)
    summary["any_below_floor1"] = any(float(mpf(r_[b]["E1_minus_floor1"])) < 0 for r_ in rows for b in ("r-1", "r+1"))
    return {"label": label, "rows": rows, "summary": summary}


def producer_crosscheck(raw):
    sys.path.insert(0, IMPL)
    import e_eval  # noqa: E402
    worst = 0.0
    n = 0
    for rec in raw["primes"]:
        r = int(rec["r"])
        fm = dict(rec["branches"]["r-1"])
        fp = dict(rec["branches"]["r+1"])
        for f in (fm, fp):
            f["product_check"] = True
        prim = e_eval.evaluate_E(r, fm, fp)
        for bname, br in (("r-1", fm), ("r+1", fp)):
            mine = branch_eval(r, r - 1 if bname == "r-1" else r + 1, br)["E1"]
            theirs = mpf(prim["branches"][bname]["minimizing"]["E"])
            worst = max(worst, float(abs(mine - theirs)))
            n += 1
    return {"branches_compared": n, "max_abs_diff_E1_vs_producer_e_eval": worst}


def deployed_block():
    j = json.loads((OUT / "j5_j6_analysis.json").read_text())
    out = {}
    for r_ in j["rows"]:
        b = r_["branches"]
        out[r_["curve_id"]] = {"r_bits": r_["r_bits"], "role": r_["role"],
                               "E1_r-1": b["r-1"]["E1_frozen_expr"][:12], "kind_r-1": b["r-1"]["kind"],
                               "E1_r+1": b["r+1"]["E1_frozen_expr"][:12], "kind_r+1": b["r+1"]["kind"],
                               "E2_r+1": b["r+1"]["E2_cheon_thm2_shape"][:12]}
    def cls(cid, reading):
        x = out[cid]
        v = {"r-1": (mpf(x["E1_r-1"]), x["kind_r-1"] == "exact"),
             "r+1": (mpf(x["E1_r+1"]), x["kind_r+1"] == "exact"),
             "r+1t2": (mpf(x["E2_r+1"]), x["kind_r+1"] == "exact")}
        if reading == "untyped":
            return classify([v["r-1"], v["r+1"]])
        if reading == "rminus1":
            return classify([v["r-1"]])
        if reading == "rplus1_thm2":
            return classify([v["r+1t2"]])
        return classify([v["r-1"], v["r+1t2"]])
    groups = {
        "all_10_deployed": list(out),
        "256bit_class_6": [c for c in out if 253 <= out[c]["r_bits"] <= 256],
        "256bit_class_nonpairing_4": [c for c in out if 253 <= out[c]["r_bits"] <= 256 and out[c]["role"] == "deployed"],
    }
    res = {"rows": out, "groups": {}}
    for g, members in groups.items():
        res["groups"][g] = {}
        for reading in ("untyped", "rminus1", "rplus1_thm2", "typed_union"):
            cnt = {}
            for c in members:
                k = cls(c, reading)
                cnt[k] = cnt.get(k, 0) + 1
            res["groups"][g][reading] = {"members": members, "counts": cnt, "n": len(members)}
    return res


def main():
    raw = json.loads((OUT / "ptm1_raw.json").read_text())
    report = {"python": sys.version, "mpmath_version": mpmath.__version__,
              "like_for_like": analyze(raw, "PTM-1 primary: sympy 1.14.0, 300 s/integer cap")}
    report["producer_evaluator_crosscheck"] = producer_crosscheck(raw)
    res_path = OUT / "ptm1_resolve.json"
    if res_path.exists():
        res = json.loads(res_path.read_text())
        report["resolved_supplementary"] = analyze(res, "PTM-1 supplementary: incomplete branches re-factored "
                                                        "with PARI/FLINT, NOT like-for-like")
    dep = deployed_block()
    report["deployed"] = dep
    # Fisher tests: deployed 256-bit class vs random, untyped and r-1 typed, at both undetermined extremes
    lf = report["like_for_like"]["summary"]
    fis = {}
    for reading, rkey in (("untyped", "cls_untyped"), ("rminus1", "cls_rminus1")):
        g = dep["groups"]["256bit_class_6"][reading]["counts"]
        a = g.get("escalate", 0)
        und_d = g.get("undetermined", 0)
        rc = lf[rkey]["counts"]
        k = rc.get("escalate", 0)
        u = rc.get("undetermined", 0)
        n = lf[rkey]["n"]
        fis[reading] = {
            "deployed_256_escalate_lower_upper": [a, a + und_d], "deployed_n": 6,
            "random_escalate_lower_upper": [k, k + u], "random_n": n,
            "p_two_sided_lower_lower": fisher_two_sided(a, 6 - a, k, n - k),
            "p_two_sided_upper_upper": fisher_two_sided(a + und_d, 6 - a - und_d, k + u, n - k - u),
            "p_two_sided_deployed_upper_random_lower": fisher_two_sided(a + und_d, 6 - a - und_d, k, n - k),
        }
    report["fisher_deployed256_vs_random"] = fis
    json.dump(report, sys.stdout, indent=1, default=str)


if __name__ == "__main__":
    main()

